def top(Z):
    u,s,vh=np.linalg.svd(Z); return s,u,vh
for sk in range(4):
    M=T[sk]>=0
    print('skill',sk)
    for k in (1,2,3,4):
        Z=np.where(M,np.exp(2j*np.pi*k*np.where(M,T[sk],0)/8),0)
        s,u,vh=top(Z); print('  add harmonic',k,np.round(s[:4],1).tolist())
    for k in range(1,8):
        def pc(x): return (x&1)+((x>>1)&1)+((x>>2)&1)
        Z=np.where(M,(1-2*(pc(np.where(M,T[sk],0)&k)%2)).astype(float),0.0)
        s,u,vh=top(Z); print('  xor char',k,np.round(s[:4],1).tolist())

